SELECT DATE_FORMAT(launch_date, 'yyyy-MM') AS launch_month, brand, category, SUM(CASE WHEN brand = 'Globex' THEN 1 ELSE 0 END) AS globex_count, COUNT(DISTINCT cost) AS unique_categorys, COUNT(price) AS price_count FROM products WHERE brand = 'Globex' AND category IN ('Home', 'Fashion', 'Electronics') GROUP BY DATE_FORMAT(launch_date, 'yyyy-MM'), brand, category ORDER BY price_count, category
